package cloud.gitwide.ampverse;

import android.app.*;
import android.widget.*;
import android.text.InputType;
import androidx.media3.common.MediaItem;
import java.util.*;
import org.json.*;

/** Advanced choices are kept in a draft until Apply, then the parent Save Playlist persists it. */
final class PhoneSmartEditor {
    private final Activity activity;
    private final Appearance colors;
    private final JSONObject original;
    private JSONObject draft;
    private LinearLayout body;
    PhoneSmartEditor(Activity a,Appearance c,JSONObject list){activity=a;colors=c;original=list;}
    private TextView label(String s){TextView v=new TextView(activity);v.setText(s);v.setTextColor(colors.text);v.setPadding(8,14,8,8);return v;}
    private Button button(String text,Runnable callback){Button b=new Button(activity);b.setText(text);b.setAllCaps(false);b.setTextColor(Chrome.ink(colors,false));b.setBackground(Chrome.button(colors,false));b.setOnClickListener(v->callback.run());return b;}
    private EditText input(String hint,String value,boolean numeric){EditText e=new EditText(activity);e.setTextColor(colors.text);e.setHintTextColor(colors.muted);e.setHint(hint);e.setText(value);if(numeric)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);return e;}
    private void error(Exception e){Toast.makeText(activity,e.getMessage(),Toast.LENGTH_LONG).show();}
    void show(){try{draft=new JSONObject(original.toString());body=new LinearLayout(activity);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(16,8,16,16);body.setBackgroundColor(colors.surface);ScrollView scroll=new ScrollView(activity);scroll.addView(body);draw();new AlertDialog.Builder(activity).setTitle("Smart Playlist options").setView(scroll).setPositiveButton("Apply to draft",(d,n)->{try{for(String key:new String[]{"genres","filters","excluded","preferred","recognition_song","energy_progression","recent_repeat","fallback","use_manual_cues"}){if(draft.has(key))original.put(key,draft.get(key));else original.remove(key);}}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show();}catch(Exception e){error(e);}}
    private String genreSummary(JSONArray genres){List<String> names=new ArrayList<>();for(int i=0;i<genres.length();i++)names.add(genres.optString(i));return String.join(", ",names);}
    private void draw(){body.removeAllViews();body.addView(label("Genres · any selected genre may match"));JSONArray genres=PhoneSmartRules.array(draft,"genres");body.addView(label(genres.length()==0?"All genres":genreSummary(genres)));body.addView(button("Choose genres",this::genres));body.addView(label("Analysis and track filters · every filter must match"));body.addView(label("Uses saved desktop analysis. Missing values do not match text or ranges. Recorded stems do not guarantee their audio is downloaded."));JSONArray filters=PhoneSmartRules.array(draft,"filters");for(int i=0;i<filters.length();i++){final int at=i;JSONObject f=filters.optJSONObject(i);if(f==null)continue;int index=Arrays.asList(PhoneSmartRules.FIELDS).indexOf(f.optString("field"));String title=index<0?f.optString("field"):PhoneSmartRules.LABELS[index];body.addView(button(title+" · "+summary(f),()->filterMenu(at)));}body.addView(button("+ Add filter",this::addFilter));body.addView(label("Song exceptions · sources are included automatically"));body.addView(button("Exclude songs ("+PhoneSmartRules.array(draft,"excluded").length()+")",()->songs("excluded")));body.addView(button("Prefer songs ("+PhoneSmartRules.array(draft,"preferred").length()+")",()->songs("preferred")));body.addView(button("Recognition track",this::recognition));body.addView(button("Repeat protection & cue preference",this::playbackOptions));body.addView(button("Energy progression"+(draft.has("energy_progression")?" · On":" · Off"),this::progression));}
    private String summary(JSONObject f){switch(f.optString("type")){case "Number":return f.optDouble("min")+"–"+f.optDouble("max");case "Flag":return f.optBoolean("value")?"Yes":"No";default:return (f.optBoolean("exact",true)?"is ":"contains ")+f.optString("terms");}}
    private void genres(){try{TreeSet<String> available=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);for(MediaItem song:LibraryStore.read(activity))available.addAll(PhoneSmartRules.genres(song));JSONArray selected=PhoneSmartRules.array(draft,"genres");for(int i=0;i<selected.length();i++)available.add(selected.getString(i));available.addAll(Arrays.asList("Rock","R&B","Hip-Hop","House","Pop","Jazz","Electronic"));String[] names=available.toArray(new String[0]);boolean[] checked=new boolean[names.length];for(int i=0;i<names.length;i++)for(int j=0;j<selected.length();j++)checked[i]|=PhoneSmartRules.genre(names[i]).equals(PhoneSmartRules.genre(selected.optString(j)));new AlertDialog.Builder(activity).setTitle("Genres · none means all").setMultiChoiceItems(names,checked,(d,n,v)->checked[n]=v).setPositiveButton("Use genres",(d,n)->{try{JSONArray next=new JSONArray();for(int i=0;i<names.length;i++)if(checked[i])next.put(names[i]);draft.put("genres",next);draw();}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show();}catch(Exception e){error(e);}}
    private void addFilter(){new AlertDialog.Builder(activity).setTitle("Choose filter").setItems(PhoneSmartRules.LABELS,(d,n)->{try{String field=PhoneSmartRules.FIELDS[n];JSONObject f=new JSONObject().put("field",field).put("type",PhoneSmartRules.kind(field));if(f.getString("type").equals("Number"))f.put("min",PhoneSmartRules.min(field)).put("max",PhoneSmartRules.max(field));else if(f.getString("type").equals("Flag"))f.put("value",true);else f.put("terms","").put("exact",true);editFilter(-1,f);}catch(Exception e){error(e);}}).show();}
    private void filterMenu(int index){new AlertDialog.Builder(activity).setItems(new String[]{"Edit","Remove"},(d,n)->{JSONArray filters=PhoneSmartRules.array(draft,"filters");if(n==1){filters.remove(index);draw();}else try{editFilter(index,new JSONObject(filters.getJSONObject(index).toString()));}catch(Exception e){error(e);}}).show();}
    private void editFilter(int index,JSONObject f){LinearLayout form=new LinearLayout(activity);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(16,8,16,16);form.setBackgroundColor(colors.surface);String type=f.optString("type"),field=f.optString("field");EditText low=input("From",String.valueOf(f.optDouble("min")),true),high=input("To",String.valueOf(f.optDouble("max")),true),terms=input("Value; another value",f.optString("terms"),false);Switch option=new Switch(activity);option.setTextColor(colors.text);if(type.equals("Number")){form.addView(label("From / to · "+PhoneSmartRules.min(field)+"–"+PhoneSmartRules.max(field)));form.addView(low);form.addView(high);}else if(type.equals("Flag")){option.setText("Must be Yes (off = must be No)");option.setChecked(f.optBoolean("value"));form.addView(option);}else{form.addView(label("Separate alternatives with ;"));form.addView(terms);option.setText("Exact match (off = contains)");option.setChecked(f.optBoolean("exact",true));form.addView(option);form.addView(button("Choose saved values",()->{TreeSet<String> values=new TreeSet<>();for(MediaItem song:LibraryStore.read(activity))values.addAll(PhoneSmartRules.text(activity,song,field));String[] names=values.toArray(new String[0]);boolean[] checked=new boolean[names.length];List<String> old=Arrays.asList(terms.getText().toString().split(";\\s*"));for(int i=0;i<names.length;i++)checked[i]=old.contains(names[i]);new AlertDialog.Builder(activity).setTitle("Saved values").setMultiChoiceItems(names,checked,(d,n,v)->checked[n]=v).setPositiveButton("Use values",(d,n)->{List<String> chosen=new ArrayList<>();for(int i=0;i<names.length;i++)if(checked[i])chosen.add(names[i]);terms.setText(String.join("; ",chosen));}).setNegativeButton("Cancel",null).show();}));}AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Edit "+field).setView(form).setPositiveButton("Use filter",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{if(type.equals("Number")){double lo=Double.parseDouble(low.getText().toString()),hi=Double.parseDouble(high.getText().toString());if(!Double.isFinite(lo)||!Double.isFinite(hi)||lo>hi||lo<PhoneSmartRules.min(field)||hi>PhoneSmartRules.max(field))throw new IllegalArgumentException("Enter a valid range within the displayed limits");f.put("min",lo).put("max",hi);}else if(type.equals("Flag"))f.put("value",option.isChecked());else f.put("terms",terms.getText().toString().trim()).put("exact",option.isChecked());JSONArray filters=PhoneSmartRules.array(draft,"filters");if(index<0){if(filters.length()>=64)throw new IllegalArgumentException("Maximum 64 filters");filters.put(f);}else filters.put(index,f);draft.put("filters",filters);dialog.dismiss();draw();}catch(Exception e){error(e);}}));dialog.show();}
    private void songs(String key){List<MediaItem> library=LibraryStore.read(activity);String[] names=new String[library.size()];boolean[] selected=new boolean[names.length];for(int i=0;i<names.length;i++){names[i]=String.valueOf(library.get(i).mediaMetadata.title);selected[i]=PhoneSmartRules.contains(draft.optJSONArray(key),library.get(i).mediaId);}new AlertDialog.Builder(activity).setTitle(key.equals("excluded")?"Exclude songs":"Prefer songs").setMultiChoiceItems(names,selected,(d,n,v)->selected[n]=v).setPositiveButton("Use exceptions",(d,n)->{try{JSONArray next=new JSONArray();Set<String> visible=new HashSet<>();for(MediaItem item:library)visible.add(item.mediaId);JSONArray old=PhoneSmartRules.array(draft,key);for(int i=0;i<old.length();i++)if(!visible.contains(old.optString(i)))next.put(old.optString(i));for(int i=0;i<names.length;i++)if(selected[i])next.put(library.get(i).mediaId);draft.put(key,next);draw();}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show();}
    private void recognition(){List<MediaItem> songs=LibraryStore.read(activity);String[] names=new String[songs.size()+1];names[0]="None";for(int i=0;i<songs.size();i++)names[i+1]=String.valueOf(songs.get(i).mediaMetadata.title);new AlertDialog.Builder(activity).setTitle("Recognition track · first if eligible").setItems(names,(d,n)->{try{if(n==0)draft.remove("recognition_song");else draft.put("recognition_song",songs.get(n-1).mediaId);draw();}catch(Exception e){error(e);}}).show();}
    private void playbackOptions(){LinearLayout form=new LinearLayout(activity);form.setOrientation(LinearLayout.VERTICAL);form.setBackgroundColor(colors.surface);EditText recent=input("Avoid last N songs (0–100)",String.valueOf(draft.optInt("recent_repeat",5)),true);recent.setInputType(InputType.TYPE_CLASS_NUMBER);Switch repeat=new Switch(activity),manual=new Switch(activity);repeat.setText("Continue with recent music when the queue runs out");repeat.setTextColor(colors.text);repeat.setChecked(!draft.optString("fallback","relax_recent").equals("stop"));manual.setText("Prefer approved build/drop cues for Hype");manual.setTextColor(colors.text);manual.setChecked(draft.optBoolean("use_manual_cues",true));form.addView(label("Auto DJ options · applied when this source is loaded"));form.addView(recent);form.addView(repeat);form.addView(manual);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Playback options").setView(form).setPositiveButton("Use options",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{int n=Integer.parseInt(recent.getText().toString());if(n<0||n>100)throw new IllegalArgumentException("Choose 0–100 recent songs");draft.put("recent_repeat",n).put("fallback",repeat.isChecked()?"relax_recent":"stop").put("use_manual_cues",manual.isChecked());dialog.dismiss();draw();}catch(Exception e){error(e);}}));dialog.show();}
    private void progression(){JSONObject plan=PhoneSmartRules.object(draft,"energy_progression");LinearLayout form=new LinearLayout(activity);form.setOrientation(LinearLayout.VERTICAL);form.setBackgroundColor(colors.surface);Switch enabled=new Switch(activity),hold=new Switch(activity);enabled.setText("Enable progression");enabled.setTextColor(colors.text);enabled.setChecked(draft.has("energy_progression"));hold.setText("Hold target after reaching it");hold.setTextColor(colors.text);hold.setChecked(plan.optBoolean("hold",true));EditText target=input("Target energy 1–10",String.valueOf(1+9*plan.optDouble("target",.7)),true),count=input("Transitions 1–100",String.valueOf(plan.optInt("transitions",4)),true);form.addView(enabled);form.addView(target);form.addView(count);form.addView(hold);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Energy progression").setView(form).setPositiveButton("Use progression",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{if(enabled.isChecked()){double value=Double.parseDouble(target.getText().toString());int steps=Integer.parseInt(count.getText().toString());if(!Double.isFinite(value)||value<1||value>10||steps<1||steps>100)throw new IllegalArgumentException("Energy must be 1–10; transitions 1–100");draft.put("energy_progression",new JSONObject().put("target",(value-1)/9).put("transitions",steps).put("hold",hold.isChecked()));}else draft.remove("energy_progression");dialog.dismiss();draw();}catch(Exception e){error(e);}}));dialog.show();}
}
